<script setup lang="ts">
// FR-QUALITY-001/002 / D18-API-020..026,028 / TC-QUALITY-001/002/003
import {ref,reactive,onMounted} from 'vue';import {useAuthStore} from '../../stores/auth';import {get,command,errorText,type Row,type Page} from '../../api/implemented';import {useRouter,useRoute} from 'vue-router';const auth=useAuthStore(),router=useRouter(),route=useRoute(),send=command();const rows=ref<Row[]>([]),error=ref(''),busy=ref(false),page=ref(1),total=ref(0),message=ref('');
const batch=reactive({orgId:auth.user?.orgId||'',ruleVersionId:'',batchNo:''});const issue=reactive({orgId:auth.user?.orgId||'',assetId:'',fieldId:'',ruleVersionId:'',batchId:'',summary:'',locatorKey:'recordKey',locatorValue:''});const assetChoices=ref<Row[]>([]),fieldChoices=ref<Row[]>([]);async function assetChanged(){const a=assetChoices.value.find(a=>a.id===issue.assetId);if(a)issue.orgId=String(a.orgId);issue.fieldId='';fieldChoices.value=issue.assetId?await get<Row[]>('D18-API-013',{id:issue.assetId}):[]}
const focus=ref<Row|null>(null);const selected=ref<Row|null>(null),decision=ref('CONFIRM'),relatedIssueId=ref(''),reason=ref('');
async function load(){const x=await get<Page>('D18-API-023',{}, {page:String(page.value),size:'20'});rows.value=x.items;total.value=x.total;if(route.query.issue)focus.value=await get<Row>('D18-API-025',{id:String(route.query.issue)})}
async function run(f:()=>Promise<unknown>){busy.value=true;error.value='';message.value='';try{await f();await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function register(){const {locatorKey,locatorValue,...b}=issue;const x=await send<Row>('D18-API-024',{}, {...b,locator:{[locatorKey]:locatorValue}});message.value='已登记问题 '+x.id}
async function create(q:Row){const w=await send<Row>('D18-API-028',{}, {issueId:q.id});await router.push('/workorders?order='+w.id)}
onMounted(()=>run(async()=>{await load();if(auth.permissions.includes('asset:read'))assetChoices.value=(await get<Page>('D18-API-010',{}, {status:'PUBLISHED',size:'100'})).items}));
</script><template><section><h2>质量问题</h2><p class="error" role="alert">{{error}}</p><p role="status">{{message}}</p><div v-if="focus"><h3>检测关联问题 {{focus.issueNo}}</h3><p>{{focus.summary}} · {{focus.status}}</p><button v-if="focus.status==='CANDIDATE'&&auth.permissions.includes('quality:decide')" @click="selected=focus">确认 / 合并</button><button v-if="focus.status==='CONFIRMED'&&auth.permissions.includes('workorder:dispatch')" :disabled="busy" @click="run(()=>create(focus!))">创建工单</button></div><div v-if="auth.permissions.includes('quality:register')" class="columns"><form @submit.prevent="run(async()=>{const x=await send<Row>('D18-API-021',{},batch);issue.batchId=x.id;message='批次已登记：'+x.id})"><h3>手工异常接收批次</h3><label>组织ID<input v-model="batch.orgId" required></label><label>已发布规则版本ID<input v-model="batch.ruleVersionId" required></label><label>批次编号<input v-model="batch.batchNo" required maxlength="64"></label><button :disabled="busy">登记批次</button></form><form @submit.prevent="run(register)"><h3>登记异常候选</h3><p>资产、字段和规则需已登记。本页不执行自动检测。</p><template v-if="auth.permissions.includes('asset:read')"><label>已发布资产<select v-model="issue.assetId" required @change="run(assetChanged)"><option value="">请选择资产</option><option v-for="a in assetChoices" :key="a.id" :value="a.id">{{a.name}} / {{a.assetCode}}</option></select></label><label>字段<select v-model="issue.fieldId" required><option value="">请选择字段</option><option v-for="f in fieldChoices" :key="f.id" :value="f.id">{{f.displayName}} / {{f.fieldCode}}</option></select></label></template><label v-for="field in (auth.permissions.includes('asset:read')?['orgId','ruleVersionId','batchId']:['orgId','assetId','fieldId','ruleVersionId','batchId']) as ('orgId'|'assetId'|'fieldId'|'ruleVersionId'|'batchId')[]" :key="field">{{{orgId:'组织ID',assetId:'资产ID',fieldId:'字段ID',ruleVersionId:'规则版本ID',batchId:'批次ID'}[field]}}<input v-model="issue[field]" required></label><label>问题摘要<input v-model="issue.summary" required maxlength="1000"></label><label>定位字段<input v-model="issue.locatorKey" required></label><label>定位值<input v-model="issue.locatorValue" required></label><button :disabled="busy">登记问题</button></form></div><table><thead><tr><th>编号 / 摘要</th><th>状态</th><th>资产 / 字段</th><th>操作</th></tr></thead><tbody><tr v-for="q in rows" :key="q.id"><td>{{q.issueNo}}<br>{{q.summary}}</td><td>{{q.status}}</td><td>{{q.assetId}} / {{q.fieldId}}</td><td><button v-if="q.status==='CANDIDATE'&&auth.permissions.includes('quality:decide')" @click="selected=q">确认 / 合并</button><button v-if="q.status==='CONFIRMED'&&auth.permissions.includes('workorder:dispatch')" @click="run(()=>create(q))" :disabled="busy">创建工单</button></td></tr></tbody></table><div class="actions"><button :disabled="page<=1||busy" @click="page--;run(load)">上一页</button>第{{page}}页 · 共{{total}}条<button :disabled="page*20>=total||busy" @click="page++;run(load)">下一页</button></div><form v-if="selected" @submit.prevent="run(async()=>{await send('D18-API-026',{id:selected!.id},{decision,relatedIssueId:relatedIssueId||null,reason,expectedVersion:selected!.version});selected=null})"><h3>判断问题 {{selected.id}}</h3><label>判断<select v-model="decision"><option value="CONFIRM">确认新问题</option><option value="MERGE">合并同定位未闭环问题</option></select></label><label v-if="decision==='MERGE'">合并目标问题ID<input v-model="relatedIssueId" required></label><label>判断原因<textarea v-model="reason" required maxlength="1000"/></label><button :disabled="busy">保存判断</button><button type="button" @click="selected=null">取消</button></form></section></template>